import './styles.css';
import { main } from './mainLogicModule.js';

function debounce(func, wait) {
    let timeout;
    return function(...args) {
        clearTimeout(timeout);
        timeout = setTimeout(() => func.apply(this, args), wait)
    };
};

window.addEventListener('load', () => {
    main();
    let previousWidth = document.documentElement.clientWidth;
    const debounceResizeHandler = debounce(() => {
        const currentWidth = document.documentElement.clientWidth;
        if (currentWidth !== previousWidth) {
            main();
            previousWidth = document.documentElement.clientWidth;
        }
    }, 10);
    window.addEventListener('resize', debounceResizeHandler);
});